        updatedAt: '2026-03-01T00:00:00.000Z',
        content: "import React, { useState } from 'react';\nimport { Activity, Server, Clock, AlertTriangle, RefreshCw, CheckCircle2 } from 'lucide-react';\n\ninterface ModelTelemetryRow {\n  model: string;\n  provider: string;\n  region: string;\n  p50Ms: number;\n  p95Ms: number;\n  rpm: number;\n  errorRate: number;\n}\n\nexport const App: React.FC = () => {\n  const [isRefreshing, setIsRefreshing] = useState(false);\n  const [metrics, setMetrics] = useState({\n    p95LatencyMs: 312,\n    tokenThroughput: 1842,\n    errorRatePercent: 0.02,\n    budgetSpentInr: 1248.5,\n  });\n\n  const [providers] = useState<ModelTelemetryRow[]>([\n    { model: 'claude-3-7-sonnet', provider: 'Anthropic', region: 'us-east-1', p50Ms: 182, p95Ms: 284, rpm: 420, errorRate: 0.02 },\n    { model: 'gpt-4o', provider: 'OpenAI', region: 'global-edge', p50Ms: 145, p95Ms: 230, rpm: 850, errorRate: 0.01 },\n    { model: 'gemini-2.5-pro', provider: 'Google', region: 'us-central1', p50Ms: 210, p95Ms: 345, rpm: 310, errorRate: 0.04 },\n  ]);\n\n  const syncTelemetry = () => {\n    setIsRefreshing(true);\n    setTimeout(() => {\n      setMetrics((prev) => ({\n        ...prev,\n        p95LatencyMs: Math.floor(290 + Math.random() * 35),\n        tokenThroughput: Math.floor(1780 + Math.random() * 150),\n      }));\n      setIsRefreshing(false);\n    }, 450);\n  };\n\n  return (\n    <div className=\"min-h-screen bg-[#0B0F14] text-slate-200 p-6 font-sans\">\n      <header className=\"flex items-center justify-between border-b border-slate-800 pb-5\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"w-10 h-10 rounded-xl bg-blue-500/10 border border-blue-500/30 flex items-center justify-center text-blue-400\">\n            <Activity className=\"w-5 h-5\" />\n          </div>\n          <div>\n            <h1 className=\"text-xl font-bold tracking-tight text-white\">AI Telemetry & Model Ops Studio</h1>\n            <p className=\"text-xs text-slate-400\">Real-time LLM token utilization, p95 latency, and provider error budgets.</p>\n          </div>\n        </div>\n        <button\n          onClick={syncTelemetry}\n          disabled={isRefreshing}\n          className=\"px-3.5 py-2 rounded-xl bg-slate-900 border border-slate-800 hover:bg-slate-800 text-xs font-semibold flex items-center gap-2 cursor-pointer transition-colors\"\n        >\n          <RefreshCw className={isRefreshing ? 'w-3.5 h-3.5 animate-spin text-blue-400' : 'w-3.5 h-3.5'} />\n          <span>Sync Telemetry</span>\n        </button>\n      </header>\n\n      <div className=\"grid grid-cols-1 md:grid-cols-4 gap-4 my-6\">\n        <div className=\"p-4 rounded-xl bg-slate-900/80 border border-slate-800\">\n          <span className=\"text-xs font-mono text-slate-400\">p95 Latency</span>\n          <div className=\"text-2xl font-bold font-mono text-white mt-1\">{metrics.p95LatencyMs} ms</div>\n          <div className=\"text-[11px] font-mono text-emerald-400 mt-1\">-18 ms vs 1h ago</div>\n        </div>\n        <div className=\"p-4 rounded-xl bg-slate-900/80 border border-slate-800\">\n          <span className=\"text-xs font-mono text-slate-400\">Throughput</span>\n          <div className=\"text-2xl font-bold font-mono text-white mt-1\">{metrics.tokenThroughput} tok/s</div>\n          <div className=\"text-[11px] font-mono text-emerald-400 mt-1\">+12% peak</div>\n        </div>\n        <div className=\"p-4 rounded-xl bg-slate-900/80 border border-slate-800\">\n          <span className=\"text-xs font-mono text-slate-400\">Error Rate</span>\n          <div className=\"text-2xl font-bold font-mono text-emerald-400 mt-1\">{metrics.errorRatePercent}%</div>\n          <div className=\"text-[11px] font-mono text-slate-400 mt-1\">SLO Budget: 0.1%</div>\n        </div>\n        <div className=\"p-4 rounded-xl bg-slate-900/80 border border-slate-800\">\n          <span className=\"text-xs font-mono text-slate-400\">Active Clusters</span>\n          <div className=\"text-2xl font-bold font-mono text-white mt-1\">{providers.length} Online</div>\n          <div className=\"text-[11px] font-mono text-blue-400 mt-1\">Multi-Region Edge</div>\n        </div>\n      </div>\n    </div>\n  );\n};\n\nexport default App;\n",
