        isDirectory: false,
        createdAt: '2026-03-01T00:00:00.000Z',
        updatedAt: '2026-03-01T00:00:00.000Z',
        content: "\"\"\"\nFastAPI Model Telemetry & Observability Microservice\nStreams p95 latency percentiles, error budgets, and token throughput\n\"\"\"\n\nfrom typing import List, Optional\nfrom pydantic import BaseModel, Field\nfrom datetime import datetime, timezone\n\nclass ModelTelemetrySnapshot(BaseModel):\n    provider: str\n    model_name: str\n    region: str\n    p50_latency_ms: float = Field(..., ge=0)\n    p95_latency_ms: float = Field(..., ge=0)\n    tokens_per_second: float = Field(..., ge=0)\n    error_rate_pct: float = Field(..., ge=0, le=100)\n    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\n\nclass ClusterSummary(BaseModel):\n    cluster_id: str\n    healthy: bool\n    active_models: List[str]\n    total_rpm: int\n    p95_cluster_ms: float\n\ndef compute_cluster_p95(snapshots: List[ModelTelemetrySnapshot]) -> float:\n    if not snapshots:\n        return 0.0\n    latencies = sorted([s.p95_latency_ms for s in snapshots])\n    idx = int(0.95 * len(latencies))\n    return latencies[min(idx, len(latencies) - 1)]\n\nif __name__ == '__main__':\n    print(\"AI Telemetry & Model Ops Service Initialized.\")\n",
