        updatedAt: '2026-03-01T00:00:00.000Z',
        content: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>NextGen Edge Commerce & Agent Store</title>\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    body { font-family: 'Outfit', sans-serif; }\n  </style>\n</head>\n<body class=\"min-h-screen bg-slate-900 text-slate-100 p-6 lg:p-10 font-sans\">\n  <div class=\"max-w-6xl mx-auto space-y-8\">\n    <header class=\"flex justify-between items-center border-b border-slate-800 pb-6\">\n      <div class=\"flex items-center gap-3\">\n        <div class=\"w-9 h-9 rounded-xl bg-indigo-500/10 border border-indigo-500/30 flex items-center justify-center text-indigo-400 font-bold\">\n          E\n        </div>\n        <div>\n          <h1 class=\"text-xl font-bold tracking-tight text-white\">Edge Commerce Store</h1>\n          <p class=\"text-xs text-slate-400\">High-velocity edge checkout with instant currency localization</p>\n        </div>\n      </div>\n      <div class=\"flex items-center gap-4\">\n        <span class=\"text-xs text-slate-400 font-mono\">Cart: <strong class=\"text-white\" id=\"cartCount\">0</strong> items</span>\n        <button class=\"px-4 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold transition-colors\">Checkout</button>\n      </div>\n    </header>\n\n    <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6\">\n      <div class=\"p-5 rounded-2xl bg-slate-800/80 border border-slate-700/80 flex flex-col justify-between space-y-4\">\n        <div>\n          <div class=\"aspect-video rounded-xl bg-slate-700/50 mb-4 flex items-center justify-center text-xs text-slate-400 font-mono\">\n            Hardware / AI Accelerator\n          </div>\n          <h3 class=\"text-base font-semibold text-white\">Neural Edge Tensor Node</h3>\n          <p class=\"text-xs text-slate-400 mt-1\">45 TOPS edge AI accelerator with passive heatsink and USB-C host interface.</p>\n        </div>\n        <div class=\"flex items-center justify-between pt-4 border-t border-slate-700/50\">\n          <span class=\"text-lg font-bold text-white font-mono\">&#8377;14,999</span>\n          <button onclick=\"addToCart()\" class=\"px-3 py-1.5 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-medium transition-colors\">Add to Cart</button>\n        </div>\n      </div>\n\n      <div class=\"p-5 rounded-2xl bg-slate-800/80 border border-slate-700/80 flex flex-col justify-between space-y-4\">\n        <div>\n          <div class=\"aspect-video rounded-xl bg-slate-700/50 mb-4 flex items-center justify-center text-xs text-slate-400 font-mono\">\n            Keyboards / Custom\n          </div>\n          <h3 class=\"text-base font-semibold text-white\">Obsidian Ortholinear Keyboard</h3>\n          <p class=\"text-xs text-slate-400 mt-1\">CNC milled aluminum chassis with hot-swap low profile switches and QMK/VIAL firmware.</p>\n        </div>\n        <div class=\"flex items-center justify-between pt-4 border-t border-slate-700/50\">\n          <span class=\"text-lg font-bold text-white font-mono\">&#8377;12,499</span>\n          <button onclick=\"addToCart()\" class=\"px-3 py-1.5 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-medium transition-colors\">Add to Cart</button>\n        </div>\n      </div>\n\n      <div class=\"p-5 rounded-2xl bg-slate-800/80 border border-slate-700/80 flex flex-col justify-between space-y-4\">\n        <div>\n          <div class=\"aspect-video rounded-xl bg-slate-700/50 mb-4 flex items-center justify-center text-xs text-slate-400 font-mono\">\n            Desk / Audio\n          </div>\n          <h3 class=\"text-base font-semibold text-white\">Studio Reference Monitor DAC</h3>\n          <p class=\"text-xs text-slate-400 mt-1\">Balanced dual ESS Sabre DAC with hardware volume attenuation and optical input.</p>\n        </div>\n        <div class=\"flex items-center justify-between pt-4 border-t border-slate-700/50\">\n          <span class=\"text-lg font-bold text-white font-mono\">&#8377;8,999</span>\n          <button onclick=\"addToCart()\" class=\"px-3 py-1.5 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-medium transition-colors\">Add to Cart</button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    let count = 0;\n    function addToCart() {\n      count++;\n      const el = document.getElementById('cartCount');\n      if (el) el.textContent = count;\n    }\n  </script>\n</body>\n</html>",
