        updatedAt: '2026-03-01T00:00:00.000Z',
        content: "import React, { useState } from 'react';\nimport { Bot, CheckCircle, Clock } from 'lucide-react';\n\nexport const App: React.FC = () => {\n  const [resolutionSent, setResolutionSent] = useState(false);\n\n  return (\n    <div className=\"min-h-screen bg-slate-950 text-slate-100 p-6 font-sans\">\n      <div className=\"max-w-4xl mx-auto space-y-6\">\n        <header className=\"flex justify-between items-center border-b border-slate-800 pb-4\">\n          <div className=\"flex items-center gap-3\">\n            <Bot className=\"w-6 h-6 text-emerald-400\" />\n            <div>\n              <h1 className=\"text-xl font-bold text-white\">Enterprise AI Support Cockpit</h1>\n              <p className=\"text-xs text-slate-400\">Autonomous RAG ticket classification and resolution</p>\n            </div>\n          </div>\n        </header>\n\n        <div className=\"p-5 rounded-xl bg-slate-900 border border-slate-800 space-y-3\">\n          <div className=\"flex justify-between items-center text-xs text-slate-400\">\n            <span>Ticket #4092 &bull; API Gateway 504</span>\n            <span className=\"text-emerald-400 font-mono\">Similarity: 0.94</span>\n          </div>\n          <p className=\"text-sm text-slate-300\">\n            Upstream timeout on batch vectorization. Suggested fix: set batch_size=16 and retry with exponential backoff.\n          </p>\n          <button\n            onClick={() => setResolutionSent(true)}\n            className=\"px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold\"\n          >\n            {resolutionSent ? 'Sent to Customer' : 'Approve Resolution'}\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n};\n\nexport default App;\n",
