        updatedAt: '2026-03-01T00:00:00.000Z',
        content: "\"\"\"\nFastAPI RAG Support Assistant Service\nEmbeds documents and performs cosine similarity retrieval over pgvector\n\"\"\"\n\nfrom typing import List\nfrom pydantic import BaseModel\n\nclass DocumentChunk(BaseModel):\n    id: str\n    content: str\n    similarity_score: float\n    source_file: str\n\nclass QueryRequest(BaseModel):\n    ticket_text: str\n    top_k: int = 3\n\nclass QueryResponse(BaseModel):\n    answer: str\n    chunks: List[DocumentChunk]\n    confidence_score: float\n\ndef mock_vector_search(query: str, top_k: int = 3) -> List[DocumentChunk]:\n    return [\n        DocumentChunk(\n            id=\"c1\",\n            content=\"Upstream gateway timeout occurs when payload exceeds 32 vectors.\",\n            similarity_score=0.94,\n            source_file=\"docs/sdk/batching.md\"\n        ),\n        DocumentChunk(\n            id=\"c2\",\n            content=\"Configure client concurrency to 4 workers.\",\n            similarity_score=0.89,\n            source_file=\"docs/limits/quotas.md\"\n        )\n    ]\n",
